  list(t.limitations, 1, 3, "trust.limitations").forEach((s, i) => maxLen(s, 70, `trust.limitations[${i}]`));

  const d = r.did || {};
  maxLen(d.question, 170, "did.question");
  list(d.facts, 2, 3, "did.facts").forEach((f, i) => {
    maxLen(f.label, 14, `did.facts[${i}].label`);
    maxLen(f.value, 40, `did.facts[${i}].value`);
  });
  list(d.bullets, 2, 4, "did.bullets").forEach((s, i) => maxLen(s, 115, `did.bullets[${i}]`));

  const res = r.results || {};
  list(res.stats, 1, 3, "results.stats").forEach((s, i) => {
    maxLen(s.value, 8, `results.stats[${i}].value`);
    maxLen(s.label, 70, `results.stats[${i}].label`);
    if (s.page === undefined) warnings.push(`results.stats[${i}]: no page number; every number should trace to the paper`);
  });
  list(res.bullets, 1, 3, "results.bullets").forEach((s, i) => maxLen(s, 140, `results.bullets[${i}]`));

  const m = r.meaning || {};
  maxLen(m.summary, 200, "meaning.summary");
  list(m.roles, 2, 4, "meaning.roles").forEach((x, i) => {
    maxLen(x.role, 28, `meaning.roles[${i}].role`);
    maxLen(x.line, 125, `meaning.roles[${i}].line`);
  });

  const k = r.takeaways || {};
  list(k.bullets, 2, 3, "takeaways.bullets").forEach((s, i) => maxLen(s, 110, `takeaways.bullets[${i}]`));
  maxLen(k.question, 150, "takeaways.question");

  // Writing rule from AGENTS.md: no em or en dashes anywhere.
  const raw = JSON.stringify(r);
  if (/[\u2013\u2014]/.test(raw)) errors.push("text contains an em or en dash; use a comma, colon, or new sentence");

  return { errors, warnings };
}

// ---------------------------------------------------------------- deck

function pad(n) { return String(n).padStart(3, "0"); }

function buildDeck(r, outFile) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9"; // 10 x 5.625 in
  pres.author = "Baylor Athletics Applied Performance";
  pres.title = `Research in 5 #${pad(r.number)}: ${r.paper.title}`;

  const label = `RESEARCH IN 5  ·  #${pad(r.number)}`;

  // Shared header + footer. dark = green background slide.
  function frame(n, title, dark) {
    const s = pres.addSlide();
    s.background = { color: dark ? GREEN : PAPER };
    if (dark) {
      s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.12, h: 5.625, fill: { color: GOLD }, line: { color: GOLD } });
    } else {
      s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 1.05, fill: { color: GREEN }, line: { color: GREEN } });
    }
    s.addText(label, { x: 0.45, y: 0.12, w: 5, h: 0.28, fontFace: BODY, fontSize: 10, bold: true, color: GOLD, charSpacing: 3, margin: 0 });
    s.addText(r.topic.toUpperCase(), { x: 4.55, y: 0.12, w: 5, h: 0.28, fontFace: BODY, fontSize: 10, bold: true, color: GOLD, charSpacing: 3, align: "right", margin: 0 });
    if (title) {
      s.addText(title, { x: 0.45, y: 0.42, w: 9.1, h: 0.55, fontFace: HEAD, fontSize: 26, bold: true, color: dark ? WHITE() : "FFFFFF", margin: 0, valign: "middle" });
      if (dark) s.addShape(pres.shapes.LINE, { x: 0.45, y: 1.05, w: 1.2, h: 0, line: { color: GOLD, width: 2 } });
    }
    s.addText("Baylor Athletics  ·  Applied Performance", { x: 0.45, y: 5.22, w: 6, h: 0.28, fontFace: BODY, fontSize: 9, italic: true, color: dark ? MUTED : GRAY, margin: 0 });
    s.addText(`${n} / 5`, { x: 7.55, y: 5.22, w: 2, h: 0.28, fontFace: BODY, fontSize: 9, color: dark ? MUTED : GRAY, align: "right", margin: 0 });
    return s;
  }
  function WHITE() { return "FFFFFF"; }

  const bullets = (items, opts) => items.map((t, i) => ({
    text: t,
    options: { bullet: { indent: 16 }, paraSpaceAfter: 6, breakLine: i < items.length - 1, ...opts },
  }));

  // 1. The paper
  {
    const s = frame(1, null, true);
    s.addText("THIS WEEK'S PAPER", { x: 0.45, y: 0.85, w: 6, h: 0.3, fontFace: BODY, fontSize: 11, bold: true, color: MUTED, charSpacing: 3, margin: 0 });
    const len = r.paper.title.length;
    const size = len > 120 ? 22 : len > 80 ? 26 : 30;
    s.addText(r.paper.title, { x: 0.45, y: 1.2, w: 9.1, h: 1.65, fontFace: HEAD, fontSize: size, bold: true, color: "FFFFFF", valign: "top", margin: 0 });
    s.addText(`${r.paper.authors}  ·  ${r.paper.journal}  ·  ${r.paper.year}`, { x: 0.45, y: 2.9, w: 9.1, h: 0.35, fontFace: BODY, fontSize: 13, color: MUTED, margin: 0 });
    s.addText(r.hook, { x: 0.45, y: 3.35, w: 9.1, h: 0.75, fontFace: HEAD, fontSize: 16, italic: true, color: GOLD, valign: "top", margin: 0 });

    const lvl = r.trust.level;
    const pillFill = lvl === "Strong" ? GOLD : GREEN_2;
    const pillText = lvl === "Strong" ? GREEN : lvl === "Moderate" ? GOLD : MUTED;
    s.addShape(pres.shapes.ROUNDED_RECTANGLE, { x: 0.45, y: 4.35, w: 2.55, h: 0.45, rectRadius: 0.08, fill: { color: pillFill }, line: { color: lvl === "Preliminary" ? MUTED : GOLD, width: 1 } });
    s.addText(`EVIDENCE: ${lvl.toUpperCase()}`, { x: 0.45, y: 4.35, w: 2.55, h: 0.45, fontFace: BODY, fontSize: 11, bold: true, color: pillText, align: "center", valign: "middle", charSpacing: 2, margin: 0 });
    s.addText(`${r.trust.design}  ·  ${r.trust.sample}`, { x: 3.2, y: 4.35, w: 6.35, h: 0.45, fontFace: BODY, fontSize: 13, color: "FFFFFF", valign: "middle", margin: 0 });
  }

  // 2. What did the researchers do?
  {
    const s = frame(2, "What did the researchers do?", false);
    s.addShape(pres.shapes.RECTANGLE, { x: 0.45, y: 1.3, w: 5.65, h: 1.05, fill: { color: "FFFFFF" }, line: { color: "E4DFD2", width: 0.75 } });
    s.addShape(pres.shapes.RECTANGLE, { x: 0.45, y: 1.3, w: 0.08, h: 1.05, fill: { color: GOLD }, line: { color: GOLD } });
    s.addText("THE QUESTION", { x: 0.7, y: 1.36, w: 5.2, h: 0.25, fontFace: BODY, fontSize: 9, bold: true, color: GREEN, charSpacing: 2, margin: 0 });
    s.addText(r.did.question, { x: 0.7, y: 1.6, w: 5.25, h: 0.7, fontFace: HEAD, fontSize: 13, italic: true, color: INK, valign: "top", margin: 0 });
    s.addText(bullets(r.did.bullets, { fontFace: BODY, fontSize: 13, color: INK }), { x: 0.45, y: 2.55, w: 5.65, h: 2.5, valign: "top", margin: 0 });

    s.addShape(pres.shapes.RECTANGLE, { x: 6.4, y: 1.3, w: 3.15, h: 3.75, fill: { color: GREEN }, line: { color: GREEN } });
    const slot = 3.75 / r.did.facts.length;
    r.did.facts.forEach((f, i) => {
      const y = 1.3 + i * slot;
      s.addText(f.label.toUpperCase(), { x: 6.65, y: y + 0.2, w: 2.7, h: 0.25, fontFace: BODY, fontSize: 9, bold: true, color: GOLD, charSpacing: 2, margin: 0 });
      s.addText(f.value, { x: 6.65, y: y + 0.45, w: 2.75, h: slot - 0.6, fontFace: BODY, fontSize: 14, color: "FFFFFF", valign: "top", margin: 0 });
    });
  }

  // 3. What were the results?
  {
    const s = frame(3, "What were the results?", true);
    const n = r.results.stats.length;
    const gap = 0.2;
    const w = (9.1 - gap * (n - 1)) / n;
    r.results.stats.forEach((st, i) => {
      const x = 0.45 + i * (w + gap);
      s.addShape(pres.shapes.RECTANGLE, { x, y: 1.3, w, h: 1.8, fill: { color: GREEN_2 }, line: { color: GREEN_2 } });
      s.addShape(pres.shapes.RECTANGLE, { x, y: 1.3, w, h: 0.06, fill: { color: GOLD }, line: { color: GOLD } });
      s.addText(st.value, { x: x + 0.15, y: 1.42, w: w - 0.3, h: 0.8, fontFace: HEAD, fontSize: 34, bold: true, color: GOLD, align: "center", valign: "middle", margin: 0 });
      s.addText(st.label, { x: x + 0.15, y: 2.22, w: w - 0.3, h: 0.7, fontFace: BODY, fontSize: 12, color: "FFFFFF", align: "center", valign: "top", margin: 0 });
      if (st.page !== undefined) s.addText(`p. ${st.page}`, { x: x + w - 0.75, y: 2.85, w: 0.6, h: 0.2, fontFace: BODY, fontSize: 8, color: MUTED, align: "right", margin: 0 });
    });
    s.addText(bullets(r.results.bullets, { fontFace: BODY, fontSize: 13.5, color: "FFFFFF" }), { x: 0.45, y: 3.3, w: 9.1, h: 1.8, valign: "top", margin: 0 });
  }

  // 4. What does this mean?
  {
    const s = frame(4, "What does this mean?", false);
    s.addText(r.meaning.summary, { x: 0.45, y: 1.2, w: 9.1, h: 0.72, fontFace: HEAD, fontSize: 14, italic: true, color: GREEN, valign: "middle", margin: 0 });
    const roles = r.meaning.roles;
    const rows = Math.ceil(roles.length / 2);
    const top = 2.0, area = 2.3, rgap = 0.15;
    const h = (area - rgap * (rows - 1)) / rows;
    roles.forEach((ro, i) => {
      const x = 0.45 + (i % 2) * 4.625;
      const y = top + Math.floor(i / 2) * (h + rgap);
      s.addShape(pres.shapes.RECTANGLE, { x, y, w: 4.475, h, fill: { color: "FFFFFF" }, line: { color: "E4DFD2", width: 0.75 } });
      s.addShape(pres.shapes.RECTANGLE, { x, y, w: 0.07, h, fill: { color: GOLD }, line: { color: GOLD } });
      s.addText(ro.role.toUpperCase(), { x: x + 0.22, y: y + 0.1, w: 4.1, h: 0.25, fontFace: BODY, fontSize: 9.5, bold: true, color: GREEN, charSpacing: 2, margin: 0 });
      s.addText(ro.line, { x: x + 0.22, y: y + 0.36, w: 4.1, h: h - 0.44, fontFace: BODY, fontSize: 12, color: INK, valign: "top", margin: 0 });
    });
    s.addShape(pres.shapes.RECTANGLE, { x: 0.45, y: 4.45, w: 9.1, h: 0.62, fill: { color: TINT }, line: { color: TINT } });
    s.addText([
      { text: `HOW MUCH TO TRUST IT: ${r.trust.level.toUpperCase()}`, options: { bold: true, color: GREEN, fontSize: 10, charSpacing: 1, breakLine: true } },
      { text: `${r.trust.design}, ${r.trust.sample}. Limits: ${r.trust.limitations.join("; ")}.`, options: { color: INK, fontSize: 10.5 } },
    ], { x: 0.62, y: 4.47, w: 8.8, h: 0.58, fontFace: BODY, valign: "middle", margin: 0 });
  }

  // 5. Coaching takeaways
  {
    const s = frame(5, "Coaching takeaways", true);
    r.takeaways.bullets.forEach((t, i) => {
      const y = 1.3 + i * 0.78;
      s.addShape(pres.shapes.OVAL, { x: 0.45, y: y + 0.08, w: 0.46, h: 0.46, fill: { color: GOLD }, line: { color: GOLD } });
      s.addText(String(i + 1), { x: 0.45, y: y + 0.08, w: 0.46, h: 0.46, fontFace: HEAD, fontSize: 16, bold: true, color: GREEN, align: "center", valign: "middle", margin: 0 });
      s.addText(t, { x: 1.1, y, w: 8.45, h: 0.62, fontFace: BODY, fontSize: 15, color: "FFFFFF", valign: "middle", margin: 0 });
    });
    s.addShape(pres.shapes.RECTANGLE, { x: 0.45, y: 3.72, w: 9.1, h: 0.9, fill: { color: GREEN_2 }, line: { color: GOLD, width: 1 } });
    s.addText([
      { text: "DISCUSS IN THE THREAD", options: { bold: true, color: GOLD, fontSize: 9, charSpacing: 2, breakLine: true } },
      { text: r.takeaways.question, options: { italic: true, color: "FFFFFF", fontSize: 14, fontFace: HEAD } },
    ], { x: 0.65, y: 3.75, w: 8.7, h: 0.84, fontFace: BODY, valign: "middle", margin: 0 });
    s.addText(citation(r), { x: 0.45, y: 4.72, w: 9.1, h: 0.42, fontFace: BODY, fontSize: 8.5, color: MUTED, valign: "top", margin: 0 });
  }

  return pres.writeFile({ fileName: outFile });
}

// ---------------------------------------------------------------- text posts

function link(r) { return r.paper.doi ? `https://doi.org/${r.paper.doi}` : r.paper.url; }

function citation(r) {
  const p = r.paper;
  return `${p.authors} (${p.year}). ${p.title}. ${p.journal}. ${link(r)}`;
}

function trustLine(r) {
  const t = r.trust;
  return `${t.level}. ${t.design}, ${t.sample}. Limits: ${t.limitations.join("; ")}.`;
}

function teamsPost(r) {
  const L = [];
  L.push(`**Research in 5 · #${pad(r.number)}: ${r.paper.title}**`);
  L.push(r.hook, "");
  if (r.paper.full_text === false) L.push("_Built from the abstract; full text was not available._", "");
  L.push("**What did the researchers do?**", r.did.question);
  r.did.bullets.forEach((b) => L.push(`- ${b}`));
  L.push("", "**What were the results?**");
  r.results.stats.forEach((s) => L.push(`- **${s.value}** ${s.label}`));
  r.results.bullets.forEach((b) => L.push(`- ${b}`));
  L.push("", "**What does this mean?**", r.meaning.summary);
  r.meaning.roles.forEach((x) => L.push(`- **${x.role}:** ${x.line}`));
  L.push("", "**Coaching takeaways**");
  r.takeaways.bullets.forEach((b, i) => L.push(`${i + 1}. ${b}`));
  L.push("", `**How much to trust it:** ${trustLine(r)}`);
  L.push("", `**Discuss:** ${r.takeaways.question}`);
  L.push("", citation(r), "The 5-slide deck is attached.");
  return L.join("\n") + "\n";
}

function email(r) {
  const L = [];
  L.push(`Subject: Research in 5 #${pad(r.number)}: ${r.topic}`, "");
  L.push("Hi all,", "");
  L.push(`This week's paper: ${r.paper.title} (${r.paper.authors}, ${r.paper.journal}, ${r.paper.year}).`);
  L.push(r.hook, "");
  if (r.paper.full_text === false) L.push("Note: built from the abstract; full text was not available.", "");
  L.push("WHAT DID THE RESEARCHERS DO?", r.did.question);
  r.did.bullets.forEach((b) => L.push(`  • ${b}`));
  L.push("", "WHAT WERE THE RESULTS?");
  r.results.stats.forEach((s) => L.push(`  • ${s.value}: ${s.label}`));
  r.results.bullets.forEach((b) => L.push(`  • ${b}`));
  L.push("", "WHAT DOES THIS MEAN?", r.meaning.summary);
  r.meaning.roles.forEach((x) => L.push(`  • ${x.role}: ${x.line}`));
  L.push("", "COACHING TAKEAWAYS");
  r.takeaways.bullets.forEach((b, i) => L.push(`  ${i + 1}. ${b}`));
  L.push("", `HOW MUCH TO TRUST IT: ${trustLine(r)}`);
  L.push("", `Something to think about: ${r.takeaways.question}`);
  L.push("", "The 5-slide deck is attached as a PDF.", "", `Full paper: ${link(r)}`, "");
  return L.join("\n");
}

// ---------------------------------------------------------------- main

async function main() {
  const dir = process.argv[2];
  if (!dir) { console.error("usage: node tools/build.js reviews/<folder>"); process.exit(2); }
  const file = path.join(dir, "review.json");
  const r = JSON.parse(fs.readFileSync(file, "utf8"));

  const { errors, warnings } = validate(r);
  warnings.forEach((w) => console.log(`WARN  ${w}`));
  if (errors.length) {
    errors.forEach((e) => console.log(`ERROR ${e}`));
    console.log(`\n${errors.length} error(s). Fix review.json and rerun.`);
    process.exit(1);
  }

  const folder = path.basename(path.resolve(dir));
  const out = path.join(__dirname, "..", "build", folder);
  fs.mkdirSync(out, { recursive: true });
  const base = `RI5-${pad(r.number)}_${r.slug}`;
  await buildDeck(r, path.join(out, `${base}.pptx`));
  fs.writeFileSync(path.join(out, "teams.md"), teamsPost(r));
  fs.writeFileSync(path.join(out, "email.txt"), email(r));
  console.log(`OK    ${path.resolve(out)}`);
  console.log(`      ${base}.pptx, teams.md, email.txt`);
}

if (require.main === module) main().catch((e) => { console.error(e); process.exit(1); });

module.exports = { validate, citation };

