{
  "number": 0,
  "date": "2026-09-16",
  "slug": "sleep-extension-basketball",
  "topic": "Sleep and Performance",
  "tags": ["sleep", "basketball", "sprint", "mood", "in-season"],

  "paper": {
    "title": "The Effects of Sleep Extension on the Athletic Performance of Collegiate Basketball Players",
    "authors": "Mah et al.",
    "journal": "SLEEP",
    "year": 2011,
    "doi": "10.5665/SLEEP.1132",
    "url": "https://doi.org/10.5665/SLEEP.1132",
    "source": "zotero",
    "zotero_key": "528K3FSH",
    "full_text": true
  },

  "hook": "Most of our athletes sleep under 7 hours in season. What happens if they chase 10 hours in bed for six weeks?",

  "trust": {
    "level": "Preliminary",
    "design": "Before and after, no control group",
    "sample": "11 Stanford men's basketball players",
    "limitations": [
      "Small, single team, all men",
      "No control group, so season timing could explain gains",
      "Practice drills, not game performance"
    ]
  },

  "did": {
    "question": "If in-season college athletes sleep a lot more for several weeks, do their sprint, shooting, reaction time, and mood change?",
    "facts": [
      { "label": "Design", "value": "Own baseline vs. extension" },
      { "label": "Who", "value": "11 D1 men's basketball players" },
      { "label": "Measured", "value": "Sprint, shooting, reaction time, mood" }
    ],
    "bullets": [
      "Players kept their normal sleep for 2 to 4 weeks to set a baseline.",
      "Then for 5 to 7 weeks they aimed for at least 10 hours in bed a night, with naps encouraged.",
      "Sleep was tracked with wrist actigraphy and sleep logs through the regular season.",
      "After every practice: a timed 282 ft sprint, 10 free throws, and 15 three-pointers."
    ]
  },

  "results": {
    "stats": [
      { "value": "+111 min", "label": "more sleep per night, measured by actigraphy", "page": 4 },
      { "value": "-0.7 s", "label": "on the 282 ft sprint (16.2 to 15.5 seconds)", "page": 5 },
      { "value": "7.9→8.8", "label": "free throws made out of 10", "page": 5 }
    ],
    "bullets": [
      "Three-pointers made out of 15 rose from 10.2 to 11.6 (p. 5).",
      "Reaction time got faster, daytime sleepiness dropped, and fatigue scores fell while vigor rose (p. 4, 6).",
      "Players rated how they felt at practice higher: 6.9 to 8.8 on a 10-point scale (p. 5)."
    ]
  },

  "meaning": {
    "summary": "Sleep looks like a trainable performance lever, not just recovery. The size of the gains is uncertain because nothing was compared against a control group.",
    "roles": [
      { "role": "Strength and Conditioning", "line": "Speed gains came with no change to training. Treat sleep as part of the program, not what is left over." },
      { "role": "Sports Medicine", "line": "Baseline sleepiness was high in healthy, in-season athletes. Sleep screening belongs in routine check-ins." },
      { "role": "Mental Health", "line": "Fatigue, tension, and mood scores all improved. Sleep is a low-cost first step before other supports." },
      { "role": "Sport Coaches", "line": "Late film, early lifts, and travel cut into sleep. Schedule decisions are performance decisions." }
    ]
  },

  "takeaways": {
    "bullets": [
      "Watch sleep like training load: ask about it in check-ins and look for patterns before big weeks.",
      "Pilot a 2 to 3 week sleep push with one willing team and track sprint and wellness data.",
      "Plan travel days around sleep: protect nap windows when 10 hours in bed is not possible."
    ],
    "question": "Where does our own schedule (lifts, film, travel) cost athletes the most sleep, and what could we move?"
  }
}

