// build.js - turn one reviews/<folder>/review.json into the week's outputs.
//
//   node tools/build.js reviews/001_sleep-extension
//
// Writes to build/<folder>/:
//   RI5-001_<slug>[_vN]_light.pptx   light theme deck
//   RI5-001_<slug>[_vN]_dark.pptx    dark "telemetry" theme deck
//   teams[_vN].md                    Teams channel post
//   email[_vN].txt                   Subject line + plain-text body for Outlook
//   last-build.json                  manifest publish.ps1 reads
//
// Validation runs first. Length limits exist because pptxgenjs does not shrink
// text to fit: a long bullet silently overflows its box. Fix the words, not
// the limits.

const fs = require("fs");
const path = require("path");
const pptxgen = require("pptxgenjs");

// Type: Baylor Bears Font for display text, Agency FB for everything people read.
// Bears only has A-Z, 0-9, space and . : ! - # (lowercase folds to caps). Any other
// character would be drawn in Calibri, so bears() falls back to Agency FB bold for
// the whole string instead of mixing fonts inside a word.
// Neither font has an italic face: never set italic.
const BEARS = "Baylor Bears Font";
const FONT = "Agency FB";
const BEARS_SAFE = /^[A-Za-z0-9 .:!#-]*$/;

// Two themes from one layout. Dark follows the "Sleep to Compete" telemetry deck
// (charcoal, faint grid, gold labels, teal numbers) but keeps body text near-white:
// that deck's gold-on-black body text was hard to read.
const THEMES = {
  light: {
    bg: "FCFCFA", grid: "EEF1EE", panel: "FFFFFF", panelLine: "DDE3DF",
    title: "154734", body: "1F2A24", muted: "5F6B66", label: "B8860B", num: "B8860B",
    rule: "C9D1CC", strong: "154734", bracket: "154734",
    scaleOn: "154734", scaleOff: "E3E8E4",
    seriesA: "B8860B", seriesB: "154734",
    barFill: "FFB81C", barText: "12171A",
  },
  dark: {
    bg: "12171A", grid: "1B2226", panel: "171E22", panelLine: "283238",
    title: "FFFFFF", body: "E6EBED", muted: "8E9BA1", label: "FFB81C", num: "5CC3A4",
    rule: "2C363C", strong: "FFB81C", bracket: "FFB81C",
    scaleOn: "FFB81C", scaleOff: "283238",
    seriesA: "FFB81C", seriesB: "5CC3A4",
    barFill: "FFB81C", barText: "12171A",
  },
};

const LEVELS = ["Preliminary", "Moderate", "Strong"]; // weakest to strongest

// Baylor department names. Not "Strength and Conditioning", "Sports Medicine",
// or "Sport Science": Eric's staff use these names instead.
const ROLES = ["Athletic Performance", "Athletic Medicine", "Applied Performance", "Nutrition", "Mental Health", "Sport Coaches", "Leadership"];

// Section titles are Eric's four questions, in the caps statement form Bears can
// set (it has no "?"). The Teams post and email keep the question form.
const SECTIONS = ["WHAT THE RESEARCHERS DID", "WHAT THEY FOUND", "WHAT IT MEANS", "COACHING TAKEAWAYS"];

// ---------------------------------------------------------------- validation

function validate(r) {
  const errors = [];
  const warnings = [];
  const need = (cond, msg) => { if (!cond) errors.push(msg); };
  const maxLen = (s, n, where) => {
    if (typeof s !== "string" || !s.trim()) errors.push(`${where}: missing`);
    else if (s.length > n) errors.push(`${where}: ${s.length} chars, limit ${n}: "${s.slice(0, 50)}..."`);
  };
  const list = (arr, min, max, where) => {
    if (!Array.isArray(arr)) { errors.push(`${where}: missing list`); return []; }
    if (arr.length < min || arr.length > max) errors.push(`${where}: ${arr.length} items, need ${min}-${max}`);
    return arr;
  };
  const num = (v, where) => { if (typeof v !== "number" || !isFinite(v)) errors.push(`${where}: number required`); };

  need(Number.isInteger(r.number) && r.number >= 0, "number: integer >= 0 required");
  need(r.version === undefined || (Number.isInteger(r.version) && r.version >= 1), "version: integer >= 1 when set");
  need(/^\d{4}-\d{2}-\d{2}$/.test(r.date || ""), "date: YYYY-MM-DD required");
  need(/^[a-z0-9-]+$/.test(r.slug || ""), "slug: lowercase kebab-case required");
  maxLen(r.topic, 32, "topic");
  maxLen(r.headline, 26, "headline");
  if (r.headline && !BEARS_SAFE.test(r.headline)) errors.push(`headline: Baylor Bears Font only has letters, numbers, space and . : ! - # ("${r.headline}")`);

  const p = r.paper || {};
  maxLen(p.title, 170, "paper.title");
  maxLen(p.authors, 40, "paper.authors");
  maxLen(p.journal, 60, "paper.journal");
  need(Number.isInteger(p.year), "paper.year: integer required");
  if (!p.doi && !p.url) errors.push("paper: doi or url required");
  if (p.full_text === false) warnings.push("paper.full_text is false: review built from abstract only; say so in the post");

  maxLen(r.hook, 150, "hook");

  const t = r.trust || {};
  need(LEVELS.includes(t.level), `trust.level: one of ${LEVELS.join(", ")}`);
  maxLen(t.design, 45, "trust.design");
  maxLen(t.sample, 60, "trust.sample");
  list(t.limitations, 1, 3, "trust.limitations").forEach((s, i) => {
    maxLen(s, 70, `trust.limitations[${i}]`);
    if (/;/.test(s)) errors.push(`trust.limitations[${i}]: no semicolons; limitations are joined with "; "`);
  });

  const d = r.did || {};
  maxLen(d.question, 170, "did.question");
  list(d.facts, 2, 3, "did.facts").forEach((f, i) => {
    maxLen(f.label, 14, `did.facts[${i}].label`);
    maxLen(f.value, 40, `did.facts[${i}].value`);
  });
  list(d.bullets, 2, 4, "did.bullets").forEach((s, i) => maxLen(s, 115, `did.bullets[${i}]`));

  const res = r.results || {};
  list(res.stats, 1, 3, "results.stats").forEach((s, i) => {
    maxLen(s.value, 8, `results.stats[${i}].value`);
    maxLen(s.label, 70, `results.stats[${i}].label`);
    if (s.page === undefined) warnings.push(`results.stats[${i}]: no page number; every number should trace to the paper`);
  });
  list(res.bullets, 1, 3, "results.bullets").forEach((s, i) => maxLen(s, 140, `results.bullets[${i}]`));
  if (res.chart !== undefined) {
    const c = res.chart;
    maxLen(c.title, 60, "results.chart.title");
    maxLen(c.a_label, 20, "results.chart.a_label");
    maxLen(c.b_label, 20, "results.chart.b_label");
    maxLen(c.source, 60, "results.chart.source");
    list(c.rows, 2, 8, "results.chart.rows").forEach((row, i) => {
      maxLen(row.label, 22, `results.chart.rows[${i}].label`);
      ["a", "b"].forEach((k) => {
        if (!Array.isArray(row[k]) || row[k].length !== 2) errors.push(`results.chart.rows[${i}].${k}: [mean, sd] required`);
        else { num(row[k][0], `results.chart.rows[${i}].${k}[0]`); num(row[k][1], `results.chart.rows[${i}].${k}[1]`); }
      });
    });
  } else if (res.table !== undefined) {
    const tb = res.table;
    const cols = list(tb.columns, 3, 5, "results.table.columns");
    cols.forEach((c, i) => maxLen(c, 22, `results.table.columns[${i}]`));
    list(tb.rows, 1, 8, "results.table.rows").forEach((row, i) => {
      if (!Array.isArray(row) || row.length !== cols.length) errors.push(`results.table.rows[${i}]: needs ${cols.length} cells`);
      else row.forEach((c, j) => maxLen(String(c), 22, `results.table.rows[${i}][${j}]`));
    });
    maxLen(tb.source, 60, "results.table.source");
  } else {
    warnings.push("results.chart and results.table missing: slide 3 shows key numbers only");
  }

  const m = r.meaning || {};
  maxLen(m.summary, 200, "meaning.summary");
  list(m.roles, 2, 4, "meaning.roles").forEach((x, i) => {
    if (!ROLES.includes(x.role)) errors.push(`meaning.roles[${i}].role: "${x.role}" is not a department name; use one of ${ROLES.join(", ")}`);
    maxLen(x.line, 125, `meaning.roles[${i}].line`);
  });

  const k = r.takeaways || {};
  list(k.bullets, 2, 3, "takeaways.bullets").forEach((s, i) => maxLen(s, 110, `takeaways.bullets[${i}]`));
  maxLen(k.question, 150, "takeaways.question");
  maxLen(k.bottom_line, 80, "takeaways.bottom_line");

  // Writing rule from AGENTS.md: no em or en dashes anywhere.
  const raw = JSON.stringify(r);
  if (/[\u2013\u2014]/.test(raw)) errors.push("text contains an em or en dash; use a comma, colon, or new sentence");

  return { errors, warnings };
}

// ---------------------------------------------------------------- deck

function pad(n) { return String(n).padStart(3, "0"); }

function buildDeck(r, outFile, th) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9"; // 10 x 5.625 in
  pres.author = "Baylor Athletics Applied Performance";
  pres.title = `Research in 5 #${pad(r.number)}: ${r.paper.title}`;

  const X = 0.6;   // left margin
  const W = 8.8;   // content width
  const T = { fontFace: FONT, margin: 0 };

  // Display text in Bears, or Agency FB bold when the string has a glyph Bears lacks.
  const bears = (text) => {
    const up = String(text).toUpperCase();
    return BEARS_SAFE.test(up) ? { text: up, face: BEARS, bold: false } : { text: up, face: FONT, bold: true };
  };
  const display = (s, text, o) => {
    const b = bears(text);
    s.addText(b.text, { ...T, ...o, fontFace: b.face, bold: b.bold });
  };

  const line = (s, x, y, w, h, color, width) =>
    s.addShape(pres.shapes.LINE, { x, y, w, h, line: { color, width } });
  const rule = (s, x, y, w, color = th.rule, width = 0.75) => line(s, x, y, w, 0, color, width);

  // Faint 0.5 in grid, the telemetry look. Drawn in both themes; barely visible on light.
  const grid = (s) => {
    for (let gx = 0.5; gx < 10; gx += 0.5) line(s, gx, 0, 0, 5.625, th.grid, 0.5);
    for (let gy = 0.5; gy < 5.625; gy += 0.5) line(s, 0, gy, 10, 0, th.grid, 0.5);
  };

  // Panel with corner brackets.
  const panel = (s, x, y, w, h) => {
    s.addShape(pres.shapes.RECTANGLE, { x, y, w, h, fill: { color: th.panel }, line: { color: th.panelLine, width: 0.75 } });
    const L = 0.16, c = th.bracket, wt = 1.75;
    line(s, x, y, L, 0, c, wt); line(s, x, y, 0, L, c, wt);
    line(s, x + w - L, y + h, L, 0, c, wt); line(s, x + w, y + h - L, 0, L, c, wt);
  };

  const slide = () => {
    const s = pres.addSlide();
    s.background = { color: th.bg };
    grid(s);
    return s;
  };

  const section = (i) => {
    const s = slide();
    display(s, `0${i + 1}`, { x: X, y: 0.36, w: 0.75, h: 0.72, fontSize: 36, color: th.num, valign: "bottom" });
    display(s, SECTIONS[i], { x: X + 0.78, y: 0.36, w: W - 0.78, h: 0.72, fontSize: 38, color: th.title, valign: "bottom" });
    rule(s, X, 1.18, W, th.strong, 1.25);
    return s;
  };

  // 1. The paper
  {
    const s = slide();
    s.addText([
      { text: "BAYLOR ATHLETICS  :  ", options: { color: th.muted } },
      { text: "APPLIED PERFORMANCE", options: { color: th.label } },
    ], { ...T, x: X, y: 0.3, w: 6, h: 0.35, fontFace: BEARS, fontSize: 15 });
    display(s, `Research in 5  :  #${pad(r.number)}`, { x: X + W - 3.5, y: 0.3, w: 3.5, h: 0.35, fontSize: 15, color: th.label, align: "right" });
    rule(s, X, 0.75, W);

    display(s, r.headline, { x: X, y: 0.9, w: W, h: 0.95, fontSize: 58, color: th.title, valign: "middle" });
    s.addText(`${r.topic}  :  ${r.paper.authors} ${r.paper.year}  :  ${r.paper.journal}`.toUpperCase(),
      { ...T, x: X, y: 1.9, w: W, h: 0.38, fontSize: 19, bold: true, color: th.label });
    const abstractNote = r.paper.full_text === false ? " (summary based on the abstract)" : "";
    s.addText(r.paper.title + abstractNote, { ...T, x: X, y: 2.38, w: W, h: 0.95, fontSize: 21, color: th.body, valign: "top" });
    rule(s, X, 3.45, W);

    s.addText(r.hook, { ...T, x: X, y: 3.72, w: 5.2, h: 1.35, fontSize: 23, color: th.body, valign: "top" });

    const px = 6.15, py = 3.65, pw = 3.25, ph = 1.5;
    panel(s, px, py, pw, ph);
    display(s, "Evidence", { x: px + 0.18, y: py + 0.12, w: 2, h: 0.3, fontSize: 15, color: th.label });
    const sw = pw - 0.36, gap = 0.06, step = (sw - gap * 2) / 3, filled = LEVELS.indexOf(r.trust.level);
    LEVELS.forEach((lv, i) => {
      const x = px + 0.18 + i * (step + gap);
      const on = i <= filled;
      s.addShape(pres.shapes.RECTANGLE, { x, y: py + 0.48, w: step, h: 0.14, fill: { color: on ? th.scaleOn : th.scaleOff }, line: { color: on ? th.scaleOn : th.scaleOff, width: 0 } });
      s.addText(lv, { ...T, x, y: py + 0.66, w: step, h: 0.26, fontSize: 13, bold: i === filled, color: i === filled ? th.strong : th.muted });
    });
    s.addText(`${r.trust.design}\n${r.trust.sample}`, { ...T, x: px + 0.18, y: py + 0.95, w: sw, h: 0.5, fontSize: 13, color: th.muted, valign: "top" });
  }

  // 2. What the researchers did
  {
    const s = section(0);
    s.addText(r.did.question, { ...T, x: X, y: 1.35, w: W, h: 0.8, fontSize: 23, color: th.body, valign: "top" });

    const top = 2.3, bottom = 5.15, lw = 5.25;
    const rowH = (bottom - top) / r.did.bullets.length;
    r.did.bullets.forEach((b, i) => {
      const y = top + i * rowH;
      rule(s, X, y, lw);
      display(s, String(i + 1), { x: X, y: y + 0.08, w: 0.35, h: 0.4, fontSize: 20, color: th.num, valign: "top" });
      s.addText(b, { ...T, x: X + 0.4, y: y + 0.08, w: lw - 0.4, h: rowH - 0.12, fontSize: 17, color: th.body, valign: "top" });
    });

    const sx = 6.15, sw = 3.25;
    panel(s, sx, top, sw, bottom - top);
    const slot = (bottom - top - 0.2) / r.did.facts.length;
    r.did.facts.forEach((f, i) => {
      const y = top + 0.12 + i * slot;
      if (i > 0) rule(s, sx + 0.18, y, sw - 0.36);
      display(s, f.label, { x: sx + 0.18, y: y + 0.1, w: sw - 0.36, h: 0.28, fontSize: 14, color: th.label });
      s.addText(f.value, { ...T, x: sx + 0.18, y: y + 0.4, w: sw - 0.36, h: slot - 0.48, fontSize: 20, bold: true, color: th.title, valign: "top" });
    });
  }

  // 3. What they found
  {
    const s = section(1);
    const top = 1.4;
    const stats = r.results.stats;
    const pageLabel = (pg) => (typeof pg === "number" ? `p. ${pg}` : String(pg));

    // Key numbers down the left.
    const lw = 2.55, slot = 3.75 / stats.length;
    stats.forEach((st, i) => {
      const y = top + i * slot;
      if (i > 0) rule(s, X, y - 0.05, lw);
      s.addText(st.value, { ...T, x: X, y, w: lw, h: 0.7, fontSize: 44, bold: true, color: i === 0 ? th.label : th.title, valign: "top" });
      const note = st.page !== undefined ? ` (${pageLabel(st.page)})` : "";
      s.addText(st.label + note, { ...T, x: X, y: y + 0.68, w: lw, h: slot - 0.78, fontSize: 14, color: th.muted, valign: "top" });
    });

    const rx = 3.45, rw = X + W - rx;
    let bottomOfFigure;
    if (r.results.chart) {
      // Mean ± SD per row for two conditions, plotted from the paper's own table.
      // Rows can sit on very different values (e.g. 87 vs 176 degrees), so each row is
      // centered on its own midpoint with one shared width. No new numbers are shown.
      const c = r.results.chart;
      const ph = 2.72;
      panel(s, rx, top, rw, ph);
      display(s, c.title, { x: rx + 0.18, y: top + 0.1, w: rw - 2.6, h: 0.28, fontSize: 13, color: th.label });
      const legend = (x, color, text) => {
        s.addShape(pres.shapes.OVAL, { x, y: top + 0.17, w: 0.12, h: 0.12, fill: { color }, line: { color, width: 0 } });
        s.addText(text, { ...T, x: x + 0.17, y: top + 0.1, w: 1.1, h: 0.26, fontSize: 13, color: th.body });
      };
      legend(rx + rw - 2.45, th.seriesA, c.a_label);
      legend(rx + rw - 1.2, th.seriesB, c.b_label);

      const labelW = 1.45, valW = 1.25, plotX = rx + 0.18 + labelW, plotW = rw - 0.36 - labelW - valW;
      const half = Math.ceil(Math.max(...c.rows.map((row) => Math.abs(row.a[0] - row.b[0]) / 2 + Math.max(row.a[1], row.b[1]))) * 1.05);
      const rowsTop = top + 0.48, rowsH = ph - 0.48 - 0.32, rh = rowsH / c.rows.length;
      c.rows.forEach((row, i) => {
        const y = rowsTop + i * rh, mid = y + rh / 2;
        const center = (row.a[0] + row.b[0]) / 2;
        const xv = (v) => plotX + plotW / 2 + ((v - center) / half) * (plotW / 2);
        if (i > 0) rule(s, rx + 0.18, y, rw - 0.36, th.panelLine, 0.5);
        s.addText(row.label, { ...T, x: rx + 0.18, y, w: labelW, h: rh, fontSize: 13, color: th.body, valign: "middle" });
        line(s, plotX + plotW / 2, y + 0.04, 0, rh - 0.08, th.panelLine, 0.5);
        [["a", -0.055, th.seriesA], ["b", 0.055, th.seriesB]].forEach(([k, dy, color]) => {
          const [mean, sd] = row[k];
          line(s, xv(mean - sd), mid + dy, xv(mean + sd) - xv(mean - sd), 0, color, 1.5);
          s.addShape(pres.shapes.OVAL, { x: xv(mean) - 0.045, y: mid + dy - 0.045, w: 0.09, h: 0.09, fill: { color }, line: { color, width: 0 } });
        });
        s.addText([
          { text: row.a[0].toFixed(2), options: { color: th.seriesA } },
          { text: "  /  ", options: { color: th.muted } },
          { text: row.b[0].toFixed(2), options: { color: th.seriesB } },
        ], { ...T, x: rx + rw - 0.18 - valW, y, w: valW, h: rh, fontSize: 13, align: "right", valign: "middle" });
      });
      s.addText(`Dot = mean, bar = ±1 SD. Each row is centered on its own midpoint, ±${half}${c.unit || ""} wide.`,
        { ...T, x: rx + 0.18, y: top + ph - 0.3, w: rw - 0.36, h: 0.24, fontSize: 11, color: th.muted });
      s.addText(c.source, { ...T, x: rx, y: top + ph + 0.04, w: rw, h: 0.24, fontSize: 12, color: th.muted });
      bottomOfFigure = top + ph + 0.3;
    } else if (r.results.table) {
      const tb = r.results.table;
      const ncol = tb.columns.length;
      const firstW = rw * (ncol > 3 ? 0.34 : 0.44);
      const colW = [firstW, ...Array(ncol - 1).fill((rw - firstW) / (ncol - 1))];
      const none = { type: "none" };
      const cell = (text, o = {}) => ({ text: String(text), options: { fontFace: FONT, fontSize: 14, color: th.body, margin: [0.02, 0.04, 0.02, 0.04], valign: "middle", border: [none, none, { pt: 0.75, color: th.rule }, none], ...o } });
      const header = tb.columns.map((col, j) => cell(col, { bold: true, color: th.label, align: j === 0 ? "left" : "right", border: [none, none, { pt: 1.25, color: th.strong }, none] }));
      const body = tb.rows.map((row) => row.map((col, j) => cell(col, { align: j === 0 ? "left" : "right" })));
      const rowH = Math.min(0.28, 2.5 / (tb.rows.length + 1));
      s.addTable([header, ...body], { x: rx, y: top, w: rw, colW, rowH });
      const tableBottom = top + rowH * (tb.rows.length + 1);
      s.addText(tb.source, { ...T, x: rx, y: tableBottom + 0.04, w: rw, h: 0.25, fontSize: 12, color: th.muted });
      bottomOfFigure = tableBottom + 0.3;
    } else {
      bottomOfFigure = top;
    }

    const by = bottomOfFigure + 0.08;
    s.addText(r.results.bullets.map((b, i) => ({ text: b, options: { bullet: { indent: 12 }, paraSpaceAfter: 2, breakLine: i < r.results.bullets.length - 1 } })),
      { ...T, x: rx, y: by, w: rw, h: 5.35 - by, fontSize: 13.5, color: th.body, valign: "top" });
  }

  // 4. What it means
  {
    const s = section(2);
    s.addText(r.meaning.summary, { ...T, x: X, y: 1.35, w: W, h: 0.8, fontSize: 23, color: th.body, valign: "top" });

    const roles = r.meaning.roles;
    const rows = Math.ceil(roles.length / 2);
    const top = 2.3, area = 1.95, colW = 4.2, colGap = W - colW * 2;
    const h = area / rows;
    roles.forEach((ro, i) => {
      const x = X + (i % 2) * (colW + colGap);
      const y = top + Math.floor(i / 2) * h;
      rule(s, x, y, colW);
      display(s, ro.role, { x, y: y + 0.07, w: colW, h: 0.3, fontSize: 16, color: th.label });
      s.addText(ro.line, { ...T, x, y: y + 0.38, w: colW, h: h - 0.44, fontSize: 16, color: th.body, valign: "top" });
    });

    rule(s, X, 4.4, W, th.strong, 1.25);
    display(s, `How much to trust it  :  ${r.trust.level}`, { x: X, y: 4.5, w: W, h: 0.3, fontSize: 16, color: th.title });
    s.addText(`${r.trust.design}, ${r.trust.sample}. Limits: ${limits(r)}.`, { ...T, x: X, y: 4.82, w: W, h: 0.5, fontSize: 15, color: th.body, valign: "top" });
  }

  // 5. Coaching takeaways
  {
    const s = section(3);
    const items = r.takeaways.bullets, gap = 0.2;
    const cw = (W - gap * (items.length - 1)) / items.length, ch = 1.8, top = 1.4;
    items.forEach((t, i) => {
      const x = X + i * (cw + gap);
      panel(s, x, top, cw, ch);
      display(s, `0${i + 1}`, { x: x + 0.2, y: top + 0.14, w: 1, h: 0.5, fontSize: 30, color: th.num, valign: "top" });
      s.addText(t, { ...T, x: x + 0.2, y: top + 0.68, w: cw - 0.4, h: ch - 0.8, fontSize: 18, color: th.body, valign: "top" });
    });

    display(s, "For discussion", { x: X, y: 3.36, w: W, h: 0.3, fontSize: 15, color: th.label });
    s.addText(r.takeaways.question, { ...T, x: X, y: 3.66, w: W, h: 0.66, fontSize: 21, color: th.body, valign: "top" });

    s.addShape(pres.shapes.RECTANGLE, { x: X, y: 4.42, w: W, h: 0.5, fill: { color: th.barFill }, line: { color: th.barFill, width: 0 } });
    s.addText([
      { text: "BOTTOM LINE:  ", options: { fontFace: BEARS, fontSize: 17 } },
      { text: r.takeaways.bottom_line, options: { fontFace: FONT, bold: true, fontSize: 18 } },
    ], { ...T, x: X + 0.25, y: 4.42, w: W - 0.5, h: 0.5, color: th.barText, valign: "middle" });

    s.addText(citation(r), { ...T, x: X, y: 5.02, w: W, h: 0.4, fontSize: 10.5, color: th.muted, valign: "top" });
  }

  return pres.writeFile({ fileName: outFile });
}

// ---------------------------------------------------------------- text posts

function link(r) { return r.paper.doi ? `https://doi.org/${r.paper.doi}` : r.paper.url; }

function citation(r) {
  const p = r.paper;
  return `${p.authors} (${p.year}). ${p.title}. ${p.journal}. ${link(r)}`;
}

// "Small sample; no control group" reads better than "Small sample; No control group".
function limits(r) {
  return r.trust.limitations.map((s, i) => (i === 0 ? s : s.charAt(0).toLowerCase() + s.slice(1))).join("; ");
}

function trustLine(r) {
  const t = r.trust;
  return `${t.level}. ${t.design}, ${t.sample}. Limits: ${limits(r)}.`;
}

function teamsPost(r) {
  const L = [];
  L.push(`**Research in 5 · #${pad(r.number)}: ${r.paper.title}**`);
  L.push(r.hook, "");
  if (r.paper.full_text === false) L.push("_Built from the abstract; full text was not available._", "");
  L.push("**What did the researchers do?**", r.did.question);
  r.did.bullets.forEach((b) => L.push(`- ${b}`));
  L.push("", "**What were the results?**");
  r.results.stats.forEach((s) => L.push(`- **${s.value}** ${s.label}`));
  r.results.bullets.forEach((b) => L.push(`- ${b}`));
  L.push("", "**What does this mean?**", r.meaning.summary);
  r.meaning.roles.forEach((x) => L.push(`- **${x.role}:** ${x.line}`));
  L.push("", "**Coaching takeaways**");
  r.takeaways.bullets.forEach((b, i) => L.push(`${i + 1}. ${b}`));
  L.push("", `**Bottom line:** ${r.takeaways.bottom_line}`);
  L.push("", `**How much to trust it:** ${trustLine(r)}`);
  L.push("", `**Discuss:** ${r.takeaways.question}`);
  L.push("", citation(r), "The 5-slide deck is attached.");
  return L.join("\n") + "\n";
}

function email(r) {
  const L = [];
  L.push(`Subject: Research in 5 #${pad(r.number)}: ${r.topic}`, "");
  L.push("Hi all,", "");
  L.push(`This week's paper: ${r.paper.title} (${r.paper.authors}, ${r.paper.journal}, ${r.paper.year}).`);
  L.push(r.hook, "");
  if (r.paper.full_text === false) L.push("Note: built from the abstract; full text was not available.", "");
  L.push("WHAT DID THE RESEARCHERS DO?", r.did.question);
  r.did.bullets.forEach((b) => L.push(`  • ${b}`));
  L.push("", "WHAT WERE THE RESULTS?");
  r.results.stats.forEach((s) => L.push(`  • ${s.value}: ${s.label}`));
  r.results.bullets.forEach((b) => L.push(`  • ${b}`));
  L.push("", "WHAT DOES THIS MEAN?", r.meaning.summary);
  r.meaning.roles.forEach((x) => L.push(`  • ${x.role}: ${x.line}`));
  L.push("", "COACHING TAKEAWAYS");
  r.takeaways.bullets.forEach((b, i) => L.push(`  ${i + 1}. ${b}`));
  L.push("", `BOTTOM LINE: ${r.takeaways.bottom_line}`);
  L.push("", `HOW MUCH TO TRUST IT: ${trustLine(r)}`);
  L.push("", `Something to think about: ${r.takeaways.question}`);
  L.push("", "The 5-slide deck is attached as a PDF.", "", `Full paper: ${link(r)}`, "");
  return L.join("\n");
}

// ---------------------------------------------------------------- main

async function main() {
  const dir = process.argv[2];
  if (!dir) { console.error("usage: node tools/build.js reviews/<folder>"); process.exit(2); }
  const file = path.join(dir, "review.json");
  const r = JSON.parse(fs.readFileSync(file, "utf8"));

  const { errors, warnings } = validate(r);
  warnings.forEach((w) => console.log(`WARN  ${w}`));
  if (errors.length) {
    errors.forEach((e) => console.log(`ERROR ${e}`));
    console.log(`\n${errors.length} error(s). Fix review.json and rerun.`);
    process.exit(1);
  }

  const folder = path.basename(path.resolve(dir));
  const out = path.join(__dirname, "..", "build", folder);
  fs.mkdirSync(out, { recursive: true });
  // version 2+ gets a _vN suffix so earlier versions on Drive are kept, not overwritten.
  const v = r.version > 1 ? `_v${r.version}` : "";
  const base = `RI5-${pad(r.number)}_${r.slug}${v}`;
  const decks = [];
  for (const name of Object.keys(THEMES)) {
    const f = `${base}_${name}.pptx`;
    await buildDeck(r, path.join(out, f), THEMES[name]);
    decks.push({ theme: name, pptx: f });
  }
  const manifest = { decks, teams: `teams${v}.md`, email: `email${v}.txt` };
  fs.writeFileSync(path.join(out, manifest.teams), teamsPost(r));
  fs.writeFileSync(path.join(out, manifest.email), email(r));
  fs.writeFileSync(path.join(out, "last-build.json"), JSON.stringify(manifest, null, 2));
  console.log(`OK    ${path.resolve(out)}`);
  console.log(`      ${decks.map((d) => d.pptx).join(", ")}, ${manifest.teams}, ${manifest.email}`);
}

if (require.main === module) main().catch((e) => { console.error(e); process.exit(1); });

module.exports = { validate, citation };

toolUseResult.content:
// build.js - turn one reviews/<folder>/review.json into the week's outputs.
//
//   node tools/build.js reviews/001_sleep-extension
//
// Writes to build/<folder>/:
//   RI5-001_<slug>[_vN]_light.pptx   light theme deck
//   RI5-001_<slug>[_vN]_dark.pptx    dark "telemetry" theme deck
//   teams[_vN].md                    Teams channel post
//   email[_vN].txt                   Subject line + plain-text body for Outlook
//   last-build.json                  manifest publish.ps1 reads
//
// Validation runs first. Length limits exist because pptxgenjs does not shrink
// text to fit: a long bullet silently overflows its box. Fix the words, not
// the limits.

const fs = require("fs");
const path = require("path");
const pptxgen = require("pptxgenjs");

// Type: Baylor Bears Font for display text, Agency FB for everything people read.
// Bears only has A-Z, 0-9, space and . : ! - # (lowercase folds to caps). Any other
// character would be drawn in Calibri, so bears() falls back to Agency FB bold for
// the whole string instead of mixing fonts inside a word.
// Neither font has an italic face: never set italic.
const BEARS = "Baylor Bears Font";
const FONT = "Agency FB";
const BEARS_SAFE = /^[A-Za-z0-9 .:!#-]*$/;

// Two themes from one layout. Dark follows the "Sleep to Compete" telemetry deck
// (charcoal, faint grid, gold labels, teal numbers) but keeps body text near-white:
// that deck's gold-on-black body text was hard to read.
const THEMES = {
  light: {
    bg: "FCFCFA", grid: "EEF1EE", panel: "FFFFFF", panelLine: "DDE3DF",
    title: "154734", body: "1F2A24", muted: "5F6B66", label: "B8860B", num: "B8860B",
    rule: "C9D1CC", strong: "154734", bracket: "154734",
    scaleOn: "154734", scaleOff: "E3E8E4",
    seriesA: "B8860B", seriesB: "154734",
    barFill: "FFB81C", barText: "12171A",
  },
  dark: {
    bg: "12171A", grid: "1B2226", panel: "171E22", panelLine: "283238",
    title: "FFFFFF", body: "E6EBED", muted: "8E9BA1", label: "FFB81C", num: "5CC3A4",
    rule: "2C363C", strong: "FFB81C", bracket: "FFB81C",
    scaleOn: "FFB81C", scaleOff: "283238",
    seriesA: "FFB81C", seriesB: "5CC3A4",
    barFill: "FFB81C", barText: "12171A",
  },
};

const LEVELS = ["Preliminary", "Moderate", "Strong"]; // weakest to strongest

// Baylor department names. Not "Strength and Conditioning", "Sports Medicine",
// or "Sport Science": Eric's staff use these names instead.
const ROLES = ["Athletic Performance", "Athletic Medicine", "Applied Performance", "Nutrition", "Mental Health", "Sport Coaches", "Leadership"];

// Section titles are Eric's four questions, in the caps statement form Bears can
// set (it has no "?"). The Teams post and email keep the question form.
const SECTIONS = ["WHAT THE RESEARCHERS DID", "WHAT THEY FOUND", "WHAT IT MEANS", "COACHING TAKEAWAYS"];

// ---------------------------------------------------------------- validation

function validate(r) {
  const errors = [];
  const warnings = [];
  const need = (cond, msg) => { if (!cond) errors.push(msg); };
  const maxLen = (s, n, where) => {
    if (typeof s !== "string" || !s.trim()) errors.push(`${where}: missing`);
    else if (s.length > n) errors.push(`${where}: ${s.length} chars, limit ${n}: "${s.slice(0, 50)}..."`);
  };
  const list = (arr, min, max, where) => {
    if (!Array.isArray(arr)) { errors.push(`${where}: missing list`); return []; }
    if (arr.length < min || arr.length > max) errors.push(`${where}: ${arr.length} items, need ${min}-${max}`);
    return arr;
  };
  const num = (v, where) => { if (typeof v !== "number" || !isFinite(v)) errors.push(`${where}: number required`); };

  need(Number.isInteger(r.number) && r.number >= 0, "number: integer >= 0 required");
  need(r.version === undefined || (Number.isInteger(r.version) && r.version >= 1), "version: integer >= 1 when set");
  need(/^\d{4}-\d{2}-\d{2}$/.test(r.date || ""), "date: YYYY-MM-DD required");
  need(/^[a-z0-9-]+$/.test(r.slug || ""), "slug: lowercase kebab-case required");
  maxLen(r.topic, 32, "topic");
  maxLen(r.headline, 26, "headline");
  if (r.headline && !BEARS_SAFE.test(r.headline)) errors.push(`headline: Baylor Bears Font only has letters, numbers, space and . : ! - # ("${r.headline}")`);

  const p = r.paper || {};
  maxLen(p.title, 170, "paper.title");
  maxLen(p.authors, 40, "paper.authors");
  maxLen(p.journal, 60, "paper.journal");
  need(Number.isInteger(p.year), "paper.year: integer required");
  if (!p.doi && !p.url) errors.push("paper: doi or url required");
  if (p.full_text === false) warnings.push("paper.full_text is false: review built from abstract only; say so in the post");

  maxLen(r.hook, 150, "hook");

  const t = r.trust || {};
  need(LEVELS.includes(t.level), `trust.level: one of ${LEVELS.join(", ")}`);
  maxLen(t.design, 45, "trust.design");
  maxLen(t.sample, 60, "trust.sample");
  list(t.limitations, 1, 3, "trust.limitations").forEach((s, i) => {
    maxLen(s, 70, `trust.limitations[${i}]`);
    if (/;/.test(s)) errors.push(`trust.limitations[${i}]: no semicolons; limitations are joined with "; "`);
  });

  const d = r.did || {};
  maxLen(d.question, 170, "did.question");
  list(d.facts, 2, 3, "did.facts").forEach((f, i) => {
    maxLen(f.label, 14, `did.facts[${i}].label`);
    maxLen(f.value, 40, `did.facts[${i}].value`);
  });
  list(d.bullets, 2, 4, "did.bullets").forEach((s, i) => maxLen(s, 115, `did.bullets[${i}]`));

  const res = r.results || {};
  list(res.stats, 1, 3, "results.stats").forEach((s, i) => {
    maxLen(s.value, 8, `results.stats[${i}].value`);
    maxLen(s.label, 70, `results.stats[${i}].label`);
    if (s.page === undefined) warnings.push(`results.stats[${i}]: no page number; every number should trace to the paper`);
  });
  list(res.bullets, 1, 3, "results.bullets").forEach((s, i) => maxLen(s, 140, `results.bullets[${i}]`));
  if (res.chart !== undefined) {
    const c = res.chart;
    maxLen(c.title, 60, "results.chart.title");
    maxLen(c.a_label, 20, "results.chart.a_label");
    maxLen(c.b_label, 20, "results.chart.b_label");
    maxLen(c.source, 60, "results.chart.source");
    list(c.rows, 2, 8, "results.chart.rows").forEach((row, i) => {
      maxLen(row.label, 22, `results.chart.rows[${i}].label`);
      ["a", "b"].forEach((k) => {
        if (!Array.isArray(row[k]) || row[k].length !== 2) errors.push(`results.chart.rows[${i}].${k}: [mean, sd] required`);
        else { num(row[k][0], `results.chart.rows[${i}].${k}[0]`); num(row[k][1], `results.chart.rows[${i}].${k}[1]`); }
      });
    });
  } else if (res.table !== undefined) {
    const tb = res.table;
    const cols = list(tb.columns, 3, 5, "results.table.columns");
    cols.forEach((c, i) => maxLen(c, 22, `results.table.columns[${i}]`));
    list(tb.rows, 1, 8, "results.table.rows").forEach((row, i) => {
      if (!Array.isArray(row) || row.length !== cols.length) errors.push(`results.table.rows[${i}]: needs ${cols.length} cells`);
      else row.forEach((c, j) => maxLen(String(c), 22, `results.table.rows[${i}][${j}]`));
    });
    maxLen(tb.source, 60, "results.table.source");
  } else {
    warnings.push("results.chart and results.table missing: slide 3 shows key numbers only");
  }

  const m = r.meaning || {};
  maxLen(m.summary, 200, "meaning.summary");
  list(m.roles, 2, 4, "meaning.roles").forEach((x, i) => {
    if (!ROLES.includes(x.role)) errors.push(`meaning.roles[${i}].role: "${x.role}" is not a department name; use one of ${ROLES.join(", ")}`);
    maxLen(x.line, 125, `meaning.roles[${i}].line`);
  });

  const k = r.takeaways || {};
  list(k.bullets, 2, 3, "takeaways.bullets").forEach((s, i) => maxLen(s, 110, `takeaways.bullets[${i}]`));
  maxLen(k.question, 150, "takeaways.question");
  maxLen(k.bottom_line, 80, "takeaways.bottom_line");

  // Writing rule from AGENTS.md: no em or en dashes anywhere.
  const raw = JSON.stringify(r);
  if (/[–—]/.test(raw)) errors.push("text contains an em or en dash; use a comma, colon, or new sentence");

  return { errors, warnings };
}

// ---------------------------------------------------------------- deck

function pad(n) { return String(n).padStart(3, "0"); }

function buildDeck(r, outFile, th) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9"; // 10 x 5.625 in
  pres.author = "Baylor Athletics Applied Performance";
  pres.title = `Research in 5 #${pad(r.number)}: ${r.paper.title}`;

  const X = 0.6;   // left margin
  const W = 8.8;   // content width
  const T = { fontFace: FONT, margin: 0 };

  // Display text in Bears, or Agency FB bold when the string has a glyph Bears lacks.
  const bears = (text) => {
    const up = String(text).toUpperCase();
    return BEARS_SAFE.test(up) ? { text: up, face: BEARS, bold: false } : { text: up, face: FONT, bold: true };
  };
  const display = (s, text, o) => {
    const b = bears(text);
    s.addText(b.text, { ...T, ...o, fontFace: b.face, bold: b.bold });
  };

  const line = (s, x, y, w, h, color, width) =>
    s.addShape(pres.shapes.LINE, { x, y, w, h, line: { color, width } });
  const rule = (s, x, y, w, color = th.rule, width = 0.75) => line(s, x, y, w, 0, color, width);

  // Faint 0.5 in grid, the telemetry look. Drawn in both themes; barely visible on light.
  const grid = (s) => {
    for (let gx = 0.5; gx < 10; gx += 0.5) line(s, gx, 0, 0, 5.625, th.grid, 0.5);
    for (let gy = 0.5; gy < 5.625; gy += 0.5) line(s, 0, gy, 10, 0, th.grid, 0.5);
  };

  // Panel with corner brackets.
  const panel = (s, x, y, w, h) => {
    s.addShape(pres.shapes.RECTANGLE, { x, y, w, h, fill: { color: th.panel }, line: { color: th.panelLine, width: 0.75 } });
    const L = 0.16, c = th.bracket, wt = 1.75;
    line(s, x, y, L, 0, c, wt); line(s, x, y, 0, L, c, wt);
    line(s, x + w - L, y + h, L, 0, c, wt); line(s, x + w, y + h - L, 0, L, c, wt);
  };

  const slide = () => {
    const s = pres.addSlide();
    s.background = { color: th.bg };
    grid(s);
    return s;
  };

  const section = (i) => {
    const s = slide();
    display(s, `0${i + 1}`, { x: X, y: 0.36, w: 0.75, h: 0.72, fontSize: 36, color: th.num, valign: "bottom" });
    display(s, SECTIONS[i], { x: X + 0.78, y: 0.36, w: W - 0.78, h: 0.72, fontSize: 38, color: th.title, valign: "bottom" });
    rule(s, X, 1.18, W, th.strong, 1.25);
    return s;
  };

  // 1. The paper
  {
    const s = slide();
    s.addText([
      { text: "BAYLOR ATHLETICS  :  ", options: { color: th.muted } },
      { text: "APPLIED PERFORMANCE", options: { color: th.label } },
    ], { ...T, x: X, y: 0.3, w: 6, h: 0.35, fontFace: BEARS, fontSize: 15 });
    display(s, `Research in 5  :  #${pad(r.number)}`, { x: X + W - 3.5, y: 0.3, w: 3.5, h: 0.35, fontSize: 15, color: th.label, align: "right" });
    rule(s, X, 0.75, W);

    display(s, r.headline, { x: X, y: 0.9, w: W, h: 0.95, fontSize: 58, color: th.title, valign: "middle" });
    s.addText(`${r.topic}  :  ${r.paper.authors} ${r.paper.year}  :  ${r.paper.journal}`.toUpperCase(),
      { ...T, x: X, y: 1.9, w: W, h: 0.38, fontSize: 19, bold: true, color: th.label });
    const abstractNote = r.paper.full_text === false ? " (summary based on the abstract)" : "";
    s.addText(r.paper.title + abstractNote, { ...T, x: X, y: 2.38, w: W, h: 0.95, fontSize: 21, color: th.body, valign: "top" });
    rule(s, X, 3.45, W);

    s.addText(r.hook, { ...T, x: X, y: 3.72, w: 5.2, h: 1.35, fontSize: 23, color: th.body, valign: "top" });

    const px = 6.15, py = 3.65, pw = 3.25, ph = 1.5;
    panel(s, px, py, pw, ph);
    display(s, "Evidence", { x: px + 0.18, y: py + 0.12, w: 2, h: 0.3, fontSize: 15, color: th.label });
    const sw = pw - 0.36, gap = 0.06, step = (sw - gap * 2) / 3, filled = LEVELS.indexOf(r.trust.level);
    LEVELS.forEach((lv, i) => {
      const x = px + 0.18 + i * (step + gap);
      const on = i <= filled;
      s.addShape(pres.shapes.RECTANGLE, { x, y: py + 0.48, w: step, h: 0.14, fill: { color: on ? th.scaleOn : th.scaleOff }, line: { color: on ? th.scaleOn : th.scaleOff, width: 0 } });
      s.addText(lv, { ...T, x, y: py + 0.66, w: step, h: 0.26, fontSize: 13, bold: i === filled, color: i === filled ? th.strong : th.muted });
    });
    s.addText(`${r.trust.design}\n${r.trust.sample}`, { ...T, x: px + 0.18, y: py + 0.95, w: sw, h: 0.5, fontSize: 13, color: th.muted, valign: "top" });
  }

  // 2. What the researchers did
  {
    const s = section(0);
    s.addText(r.did.question, { ...T, x: X, y: 1.35, w: W, h: 0.8, fontSize: 23, color: th.body, valign: "top" });

    const top = 2.3, bottom = 5.15, lw = 5.25;
    const rowH = (bottom - top) / r.did.bullets.length;
    r.did.bullets.forEach((b, i) => {
      const y = top + i * rowH;
      rule(s, X, y, lw);
      display(s, String(i + 1), { x: X, y: y + 0.08, w: 0.35, h: 0.4, fontSize: 20, color: th.num, valign: "top" });
      s.addText(b, { ...T, x: X + 0.4, y: y + 0.08, w: lw - 0.4, h: rowH - 0.12, fontSize: 17, color: th.body, valign: "top" });
    });

    const sx = 6.15, sw = 3.25;
    panel(s, sx, top, sw, bottom - top);
    const slot = (bottom - top - 0.2) / r.did.facts.length;
    r.did.facts.forEach((f, i) => {
      const y = top + 0.12 + i * slot;
      if (i > 0) rule(s, sx + 0.18, y, sw - 0.36);
      display(s, f.label, { x: sx + 0.18, y: y + 0.1, w: sw - 0.36, h: 0.28, fontSize: 14, color: th.label });
      s.addText(f.value, { ...T, x: sx + 0.18, y: y + 0.4, w: sw - 0.36, h: slot - 0.48, fontSize: 20, bold: true, color: th.title, valign: "top" });
    });
  }

  // 3. What they found
  {
    const s = section(1);
    const top = 1.4;
    const stats = r.results.stats;
    const pageLabel = (pg) => (typeof pg === "number" ? `p. ${pg}` : String(pg));

    // Key numbers down the left.
    const lw = 2.55, slot = 3.75 / stats.length;
    stats.forEach((st, i) => {
      const y = top + i * slot;
      if (i > 0) rule(s, X, y - 0.05, lw);
      s.addText(st.value, { ...T, x: X, y, w: lw, h: 0.7, fontSize: 44, bold: true, color: i === 0 ? th.label : th.title, valign: "top" });
      const note = st.page !== undefined ? ` (${pageLabel(st.page)})` : "";
      s.addText(st.label + note, { ...T, x: X, y: y + 0.68, w: lw, h: slot - 0.78, fontSize: 14, color: th.muted, valign: "top" });
    });

    const rx = 3.45, rw = X + W - rx;
    let bottomOfFigure;
    if (r.results.chart) {
      // Mean ± SD per row for two conditions, plotted from the paper's own table.
      // Rows can sit on very different values (e.g. 87 vs 176 degrees), so each row is
      // centered on its own midpoint with one shared width. No new numbers are shown.
      const c = r.results.chart;
      const ph = 2.72;
      panel(s, rx, top, rw, ph);
      display(s, c.title, { x: rx + 0.18, y: top + 0.1, w: rw - 2.6, h: 0.28, fontSize: 13, color: th.label });
      const legend = (x, color, text) => {
        s.addShape(pres.shapes.OVAL, { x, y: top + 0.17, w: 0.12, h: 0.12, fill: { color }, line: { color, width: 0 } });
        s.addText(text, { ...T, x: x + 0.17, y: top + 0.1, w: 1.1, h: 0.26, fontSize: 13, color: th.body });
      };
      legend(rx + rw - 2.45, th.seriesA, c.a_label);
      legend(rx + rw - 1.2, th.seriesB, c.b_label);

      const labelW = 1.45, valW = 1.25, plotX = rx + 0.18 + labelW, plotW = rw - 0.36 - labelW - valW;
      const half = Math.ceil(Math.max(...c.rows.map((row) => Math.abs(row.a[0] - row.b[0]) / 2 + Math.max(row.a[1], row.b[1]))) * 1.05);
      const rowsTop = top + 0.48, rowsH = ph - 0.48 - 0.32, rh = rowsH / c.rows.length;
      c.rows.forEach((row, i) => {
        const y = rowsTop + i * rh, mid = y + rh / 2;
        const center = (row.a[0] + row.b[0]) / 2;
        const xv = (v) => plotX + plotW / 2 + ((v - center) / half) * (plotW / 2);
        if (i > 0) rule(s, rx + 0.18, y, rw - 0.36, th.panelLine, 0.5);
        s.addText(row.label, { ...T, x: rx + 0.18, y, w: labelW, h: rh, fontSize: 13, color: th.body, valign: "middle" });
        line(s, plotX + plotW / 2, y + 0.04, 0, rh - 0.08, th.panelLine, 0.5);
        [["a", -0.055, th.seriesA], ["b", 0.055, th.seriesB]].forEach(([k, dy, color]) => {
          const [mean, sd] = row[k];
          line(s, xv(mean - sd), mid + dy, xv(mean + sd) - xv(mean - sd), 0, color, 1.5);
          s.addShape(pres.shapes.OVAL, { x: xv(mean) - 0.045, y: mid + dy - 0.045, w: 0.09, h: 0.09, fill: { color }, line: { color, width: 0 } });
        });
        s.addText([
          { text: row.a[0].toFixed(2), options: { color: th.seriesA } },
          { text: "  /  ", options: { color: th.muted } },
          { text: row.b[0].toFixed(2), options: { color: th.seriesB } },
        ], { ...T, x: rx + rw - 0.18 - valW, y, w: valW, h: rh, fontSize: 13, align: "right", valign: "middle" });
      });
      s.addText(`Dot = mean, bar = ±1 SD. Each row is centered on its own midpoint, ±${half}${c.unit || ""} wide.`,
        { ...T, x: rx + 0.18, y: top + ph - 0.3, w: rw - 0.36, h: 0.24, fontSize: 11, color: th.muted });
      s.addText(c.source, { ...T, x: rx, y: top + ph + 0.04, w: rw, h: 0.24, fontSize: 12, color: th.muted });
      bottomOfFigure = top + ph + 0.3;
    } else if (r.results.table) {
      const tb = r.results.table;
      const ncol = tb.columns.length;
      const firstW = rw * (ncol > 3 ? 0.34 : 0.44);
      const colW = [firstW, ...Array(ncol - 1).fill((rw - firstW) / (ncol - 1))];
      const none = { type: "none" };
      const cell = (text, o = {}) => ({ text: String(text), options: { fontFace: FONT, fontSize: 14, color: th.body, margin: [0.02, 0.04, 0.02, 0.04], valign: "middle", border: [none, none, { pt: 0.75, color: th.rule }, none], ...o } });
      const header = tb.columns.map((col, j) => cell(col, { bold: true, color: th.label, align: j === 0 ? "left" : "right", border: [none, none, { pt: 1.25, color: th.strong }, none] }));
      const body = tb.rows.map((row) => row.map((col, j) => cell(col, { align: j === 0 ? "left" : "right" })));
      const rowH = Math.min(0.28, 2.5 / (tb.rows.length + 1));
      s.addTable([header, ...body], { x: rx, y: top, w: rw, colW, rowH });
      const tableBottom = top + rowH * (tb.rows.length + 1);
      s.addText(tb.source, { ...T, x: rx, y: tableBottom + 0.04, w: rw, h: 0.25, fontSize: 12, color: th.muted });
      bottomOfFigure = tableBottom + 0.3;
    } else {
      bottomOfFigure = top;
    }

    const by = bottomOfFigure + 0.08;
    s.addText(r.results.bullets.map((b, i) => ({ text: b, options: { bullet: { indent: 12 }, paraSpaceAfter: 2, breakLine: i < r.results.bullets.length - 1 } })),
      { ...T, x: rx, y: by, w: rw, h: 5.35 - by, fontSize: 13.5, color: th.body, valign: "top" });
  }

  // 4. What it means
  {
    const s = section(2);
    s.addText(r.meaning.summary, { ...T, x: X, y: 1.35, w: W, h: 0.8, fontSize: 23, color: th.body, valign: "top" });

    const roles = r.meaning.roles;
    const rows = Math.ceil(roles.length / 2);
    const top = 2.3, area = 1.95, colW = 4.2, colGap = W - colW * 2;
    const h = area / rows;
    roles.forEach((ro, i) => {
      const x = X + (i % 2) * (colW + colGap);
      const y = top + Math.floor(i / 2) * h;
      rule(s, x, y, colW);
      display(s, ro.role, { x, y: y + 0.07, w: colW, h: 0.3, fontSize: 16, color: th.label });
      s.addText(ro.line, { ...T, x, y: y + 0.38, w: colW, h: h - 0.44, fontSize: 16, color: th.body, valign: "top" });
    });

    rule(s, X, 4.4, W, th.strong, 1.25);
    display(s, `How much to trust it  :  ${r.trust.level}`, { x: X, y: 4.5, w: W, h: 0.3, fontSize: 16, color: th.title });
    s.addText(`${r.trust.design}, ${r.trust.sample}. Limits: ${limits(r)}.`, { ...T, x: X, y: 4.82, w: W, h: 0.5, fontSize: 15, color: th.body, valign: "top" });
  }

  // 5. Coaching takeaways
  {
    const s = section(3);
    const items = r.takeaways.bullets, gap = 0.2;
    const cw = (W - gap * (items.length - 1)) / items.length, ch = 1.8, top = 1.4;
    items.forEach((t, i) => {
      const x = X + i * (cw + gap);
      panel(s, x, top, cw, ch);
      display(s, `0${i + 1}`, { x: x + 0.2, y: top + 0.14, w: 1, h: 0.5, fontSize: 30, color: th.num, valign: "top" });
      s.addText(t, { ...T, x: x + 0.2, y: top + 0.68, w: cw - 0.4, h: ch - 0.8, fontSize: 18, color: th.body, valign: "top" });
    });

    display(s, "For discussion", { x: X, y: 3.36, w: W, h: 0.3, fontSize: 15, color: th.label });
    s.addText(r.takeaways.question, { ...T, x: X, y: 3.66, w: W, h: 0.66, fontSize: 21, color: th.body, valign: "top" });

    s.addShape(pres.shapes.RECTANGLE, { x: X, y: 4.42, w: W, h: 0.5, fill: { color: th.barFill }, line: { color: th.barFill, width: 0 } });
    s.addText([
      { text: "BOTTOM LINE:  ", options: { fontFace: BEARS, fontSize: 17 } },
      { text: r.takeaways.bottom_line, options: { fontFace: FONT, bold: true, fontSize: 18 } },
    ], { ...T, x: X + 0.25, y: 4.42, w: W - 0.5, h: 0.5, color: th.barText, valign: "middle" });

    s.addText(citation(r), { ...T, x: X, y: 5.02, w: W, h: 0.4, fontSize: 10.5, color: th.muted, valign: "top" });
  }

  return pres.writeFile({ fileName: outFile });
}

// ---------------------------------------------------------------- text posts

function link(r) { return r.paper.doi ? `https://doi.org/${r.paper.doi}` : r.paper.url; }

function citation(r) {
  const p = r.paper;
  return `${p.authors} (${p.year}). ${p.title}. ${p.journal}. ${link(r)}`;
}

// "Small sample; no control group" reads better than "Small sample; No control group".
function limits(r) {
  return r.trust.limitations.map((s, i) => (i === 0 ? s : s.charAt(0).toLowerCase() + s.slice(1))).join("; ");
}

function trustLine(r) {
  const t = r.trust;
  return `${t.level}. ${t.design}, ${t.sample}. Limits: ${limits(r)}.`;
}

function teamsPost(r) {
  const L = [];
  L.push(`**Research in 5 · #${pad(r.number)}: ${r.paper.title}**`);
  L.push(r.hook, "");
  if (r.paper.full_text === false) L.push("_Built from the abstract; full text was not available._", "");
  L.push("**What did the researchers do?**", r.did.question);
  r.did.bullets.forEach((b) => L.push(`- ${b}`));
  L.push("", "**What were the results?**");
  r.results.stats.forEach((s) => L.push(`- **${s.value}** ${s.label}`));
  r.results.bullets.forEach((b) => L.push(`- ${b}`));
  L.push("", "**What does this mean?**", r.meaning.summary);
  r.meaning.roles.forEach((x) => L.push(`- **${x.role}:** ${x.line}`));
  L.push("", "**Coaching takeaways**");
  r.takeaways.bullets.forEach((b, i) => L.push(`${i + 1}. ${b}`));
  L.push("", `**Bottom line:** ${r.takeaways.bottom_line}`);
  L.push("", `**How much to trust it:** ${trustLine(r)}`);
  L.push("", `**Discuss:** ${r.takeaways.question}`);
  L.push("", citation(r), "The 5-slide deck is attached.");
  return L.join("\n") + "\n";
}

function email(r) {
  const L = [];
  L.push(`Subject: Research in 5 #${pad(r.number)}: ${r.topic}`, "");
  L.push("Hi all,", "");
  L.push(`This week's paper: ${r.paper.title} (${r.paper.authors}, ${r.paper.journal}, ${r.paper.year}).`);
  L.push(r.hook, "");
  if (r.paper.full_text === false) L.push("Note: built from the abstract; full text was not available.", "");
  L.push("WHAT DID THE RESEARCHERS DO?", r.did.question);
  r.did.bullets.forEach((b) => L.push(`  • ${b}`));
  L.push("", "WHAT WERE THE RESULTS?");
  r.results.stats.forEach((s) => L.push(`  • ${s.value}: ${s.label}`));
  r.results.bullets.forEach((b) => L.push(`  • ${b}`));
  L.push("", "WHAT DOES THIS MEAN?", r.meaning.summary);
  r.meaning.roles.forEach((x) => L.push(`  • ${x.role}: ${x.line}`));
  L.push("", "COACHING TAKEAWAYS");
  r.takeaways.bullets.forEach((b, i) => L.push(`  ${i + 1}. ${b}`));
  L.push("", `BOTTOM LINE: ${r.takeaways.bottom_line}`);
  L.push("", `HOW MUCH TO TRUST IT: ${trustLine(r)}`);
  L.push("", `Something to think about: ${r.takeaways.question}`);
  L.push("", "The 5-slide deck is attached as a PDF.", "", `Full paper: ${link(r)}`, "");
  return L.join("\n");
}

// ---------------------------------------------------------------- main

async function main() {
  const dir = process.argv[2];
  if (!dir) { console.error("usage: node tools/build.js reviews/<folder>"); process.exit(2); }
  const file = path.join(dir, "review.json");
  const r = JSON.parse(fs.readFileSync(file, "utf8"));

  const { errors, warnings } = validate(r);
  warnings.forEach((w) => console.log(`WARN  ${w}`));
  if (errors.length) {
    errors.forEach((e) => console.log(`ERROR ${e}`));
    console.log(`\n${errors.length} error(s). Fix review.json and rerun.`);
    process.exit(1);
  }

  const folder = path.basename(path.resolve(dir));
  const out = path.join(__dirname, "..", "build", folder);
  fs.mkdirSync(out, { recursive: true });
  // version 2+ gets a _vN suffix so earlier versions on Drive are kept, not overwritten.
  const v = r.version > 1 ? `_v${r.version}` : "";
  const base = `RI5-${pad(r.number)}_${r.slug}${v}`;
  const decks = [];
  for (const name of Object.keys(THEMES)) {
    const f = `${base}_${name}.pptx`;
    await buildDeck(r, path.join(out, f), THEMES[name]);
    decks.push({ theme: name, pptx: f });
  }
  const manifest = { decks, teams: `teams${v}.md`, email: `email${v}.txt` };
  fs.writeFileSync(path.join(out, manifest.teams), teamsPost(r));
  fs.writeFileSync(path.join(out, manifest.email), email(r));
  fs.writeFileSync(path.join(out, "last-build.json"), JSON.stringify(manifest, null, 2));
  console.log(`OK    ${path.resolve(out)}`);
  console.log(`      ${decks.map((d) => d.pptx).join(", ")}, ${manifest.teams}, ${manifest.email}`);
}

if (require.main === module) main().catch((e) => { console.error(e); process.exit(1); });

module.exports = { validate, citation };

